import math
import itertools

def solve_small(n, rounds):
    count = 0
    for p in itertools.permutations(range(n)):
        tags = list(p)
        still_present = [True] * n
        for r in range(1, rounds + 1):
            exited = [i for i in range(n) if still_present[i] and tags[i] == i]
            for i in exited:
                still_present[i] = False
            rem = [i for i in range(n) if still_present[i]]
            if not rem: break
            new_tags = [None] * n
            for idx, i in enumerate(rem):
                new_tags[rem[(idx + 1) % len(rem)]] = tags[i]
            tags = new_tags
        if any(still_present):
            count += 1
    return count

for n in range(3, 8):
    print(f"n={n}, rounds=4: {solve_small(n, 4)}")
